import math

def check_integer(n):
    denominator = 2 * n - 1
    if denominator == 0:
        return "Undefined"

    numerator = 3 * (math.factorial(n + 2) + 1)

    if numerator % denominator == 0:
        result = numerator // denominator
        return f"Integer: {result}"
    else:
        return "Not Integer"

# Test n = 0 to 10
for n in range(11):
    print(f"n={n}: {check_integer(n)}")

